package cn.campus.schedule;
import org.json.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

final class ReminderRules {
    static final LocalTime[] TIMES={LocalTime.of(8,30),LocalTime.of(14,30),LocalTime.of(19,30)};
    static String deadlineText(JSONObject task,LocalDate today){String value=task.optString("deadline");if(value.isEmpty())return "";long n=ChronoUnit.DAYS.between(today,LocalDate.parse(value));return n<0?"【已逾期 "+(-n)+" 天】DDL "+value:n==0?"【今天截止】DDL "+value:n<=3?"【紧急 · 剩 "+n+" 天】DDL "+value:n<=7?"【剩 "+n+" 天】DDL "+value:"DDL "+value;}
    static List<JSONObject> summary(JSONObject data,LocalDate today){Map<String,JSONObject> tasks=new LinkedHashMap<>();JSONArray events=data.optJSONArray("events");if(events==null)return new ArrayList<>();for(int i=0;i<events.length();i++){JSONObject event=events.optJSONObject(i);for(JSONObject t:TaskRules.visible(event,today,today))if(!t.optBoolean("done")&&(t.optBoolean("allDay")||t.optBoolean("carried")))tasks.put(t.optString("id")+"@"+t.optString("occurrence"),t);for(JSONObject t:TaskRules.scheduled(event,today.plusDays(7))){if(t.optBoolean("done")||t.optString("deadline").isEmpty())continue;long left=ChronoUnit.DAYS.between(today,LocalDate.parse(t.optString("deadline")));if(left<=7)tasks.putIfAbsent(t.optString("id")+"@"+t.optString("occurrence"),t);}}List<JSONObject> list=new ArrayList<>(tasks.values());list.sort(Comparator.comparing(t->t.optString("deadline").isEmpty()?"9999-12-31":t.optString("deadline")));return list;}
    static JSONObject next(JSONObject data,LocalDateTime now,boolean summary,boolean courses){JSONObject best=null;if(summary)for(LocalTime time:TIMES){LocalDateTime at=now.toLocalDate().atTime(time);if(!at.isAfter(now))at=at.plusDays(1);best=earlier(best,AiProtocol.obj("kind","summary","at",at.toString(),"date",at.toLocalDate().toString(),"key","summary@"+at));}
        if(courses&&data.optBoolean("configured")){LocalDate semester=LocalDate.parse(data.optString("semester")),first=ScheduleRules.monday(semester),last=first.plusWeeks(data.optInt("totalWeeks")).minusDays(1);LocalDate start=now.toLocalDate().isAfter(first)?now.toLocalDate():first;JSONArray all=data.optJSONArray("courses");for(LocalDate date=start;!date.isAfter(last);date=date.plusDays(1)){if(best!=null&&date.isAfter(LocalDateTime.parse(best.optString("at")).toLocalDate().plusDays(1)))break;for(int i=0;i<all.length();i++){JSONObject c=all.optJSONObject(i);if(!CourseRules.occurs(semester,date,c,data.optInt("totalWeeks")))continue;String time=data.optJSONArray("starts").optString(c.optInt("from")-1);LocalDateTime at=date.atTime(LocalTime.parse(time)).minusMinutes(15);if(!at.isAfter(now))continue;best=earlier(best,AiProtocol.obj("kind","course","at",at.toString(),"date",date.toString(),"title",c.optString("title"),"room",c.optString("room"),"start",time,"key","course@"+c.optString("id")+"@"+date));}}}return best;}
    static JSONObject earlier(JSONObject a,JSONObject b){if(a==null)return b;int compare=LocalDateTime.parse(b.optString("at")).compareTo(LocalDateTime.parse(a.optString("at")));if(compare<0)return b;if(compare==0&&!a.optString("key").equals(b.optString("key"))){JSONArray siblings=a.optJSONArray("siblings");if(siblings==null){siblings=new JSONArray();AgendaFeatures.put(a,"siblings",siblings);}siblings.put(b);}return a;}
}
